def transform(grid):
    """Mark cells where the two nonzero patterns on either side overlap."""
    sep = next(c for c in range(len(grid[0]))
               if grid[0][c] != 0 and all(row[c] == grid[0][c] for row in grid))
    left_width = sep
    right_width = len(grid[0]) - sep - 1
    if left_width != right_width:
        raise ValueError("unaligned sides")
    return [[2 if grid[r][c] != 0 and grid[r][sep + 1 + c] != 0 else 0
             for c in range(left_width)] for r in range(len(grid))]
